import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, Timer, ToolCallInput } from 'claude-code'

import type { Activity, AgentPet, Feelings, Label, MiniMood, Mood, Reaction, Situation, Traits } from '../types'
import { alertness, drift, engaged, misses, paceOf, rested, seen, stirred, stirs, urgeOf, USUAL } from './drives'
import type { Drives, State } from './drives'
import { calm, cheer, feel, idleMood, isNight, nightOf } from './feelings'
import { pickLocale, say } from './i18n'
import type { Locale, Text } from './i18n'
import type { Bandit } from '../learn/bandit'
import { novelty, see } from '../learn/recall'
import {
  annoyed,
  armOf,
  asBandit,
  asFamiliarity,
  CREDIT_MS,
  daypartOf,
  FAMILIAR_HALF_LIFE_MS,
  KNOWS,
  logLine,
  momentCode,
  ODD,
  ODD_GAP_MS,
  petted,
  pickFor,
  settle,
  tempered,
  temperOf,
} from './learning'
import type { Shown } from './learning'
import { asVisit, daysBetween, welcome } from './memory'
import type { Visit } from './memory'
import { activityIn, step } from './motion'
import type { Motion } from './motion'
import { ANNOY_MS, gazes, hover, leave, press, untouched } from './gestures'
import type { Poke, Sleep, Touch } from './gestures'
import { DEFAULT_PET, packPaths, parsePack } from './pack'
import type { Pack } from './pack'
import { artOf, encode, facingFrame, sizeOf } from './render'
import { arrived, asRhythm, AWAY_MS, expects, PATIENCE_MS } from './rhythm'
import type { Rhythm } from './rhythm'
import { FIRST_NAP_MS, isDeep } from './sleep'
import { LONG_THINK_MS, MANY_AGENTS, MANY_READS, lineFor, maySpeak, quiet, spoke } from './speech'
import type { Speaker } from './speech'
import type { Art } from './touch'
import { EMPTY_STAGE, faceFor, holdFacing, moveOnStage, sideIn } from './walk'
import type { Held, Side, Stage } from './walk'

const asleep: Activity = { mood: 'sleeping', label: { text: 'sleeping', detail: '' } }

const activity = atom({ plugin: 'pixel-pets', key: 'activity' } as const, asleep)
const reaction = atom({ plugin: 'pixel-pets', key: 'reaction' } as const, null as Reaction | null)
const override = atom({ plugin: 'pixel-pets', key: 'override' } as const, null as Activity | null)
const turnStartedAt = atom({ plugin: 'pixel-pets', key: 'turnStartedAt' } as const, null as number | null)
const lastActiveAt = atom({ plugin: 'pixel-pets', key: 'lastActiveAt' } as const, null as number | null)
const typingAt = atom({ plugin: 'pixel-pets', key: 'typingAt' } as const, null as number | null)
const agents = atom({ plugin: 'pixel-pets', key: 'agents' } as const, [] as AgentPet[])
const isHidden = atom({ plugin: 'pixel-pets', key: 'isHidden' } as const, false)
const feelings = atom({ plugin: 'pixel-pets', key: 'feelings' } as const, calm as Feelings)
const restedAt = atom({ plugin: 'pixel-pets', key: 'restedAt' } as const, null as number | null)

const REACTION_MS = 2000
const WAKING_MS = 1200
const LEAVING_MS = 1500
const LONG_TURN_MS = 2 * 60_000
// A break this long rests it, as far as getting tired goes.
const BREAK_MS = 60 * 60_000
const GREETING_MS = 2500
// A turn this long that goes well earns a bigger, longer celebration.
const LONG_WIN_MS = 5 * 60_000
const CELEBRATION_MS = 4000
// How long a line it says stays on Claude's line.
const SPEECH_MS = 4000
// How long the pet keeps watching the prompt after the last key.
const TYPING_MS = 2000
// How long it stays up when boredom gets it out of a nap, in seconds.
const STIR_SECONDS: [number, number] = [30, 90]
// How long into a nap it may talk in its sleep, in minutes.
const DREAM_MINUTES: [number, number] = [10, 20]
const AGENT_SLOT = 20
// Room kept for the " +N" that stands for agents with no slot.
const OVERFLOW_COLUMNS = 4
const MAX_AGENTS = 6
// While only the pets' frames move, the clock repaints them and redraws the band
// in full only this often, in seconds, for what changes with time alone (dozing
// off, a long turn's minutes): once a second awake, every 5 asleep.
const REDRAW_AWAKE_S = 1
const REDRAW_ASLEEP_S = 5

// What the band shows on a tick: `layout` stands for all of it but the pets'
// drawings: the main pet's `art` (`main` its key) and the agents' Raster cells by key.
type Shot = { layout: string; main: string; art: Art; rasters: Record<string, string> }
// The band as last drawn: what it showed, how to play it a tick on, and the tick
// by which something it shows runs out.
type Scene = { requestId: string; shot: Shot; play: () => Shot; redrawAt: number; isAsleep: boolean }

// One body color per subagent, picked in spawn order.
const AGENT_COLORS = [0x7cc4f2, 0x9bd57a, 0xc69af2, 0xf2d16b, 0xf28fb0, 0x6fd8c8]

const SEARCHERS = new Set(['Grep', 'Glob', 'WebFetch', 'WebSearch', 'LSP'])

// Waiting on something slow: these turn into sweating when a turn runs long.
const PATIENT: readonly Mood[] = ['thinking', 'running', 'supervising']

const short = (text: string, max = 32) => (text.length > max ? `${text.slice(0, max - 1)}…` : text)
const basename = (path: string) => path.split('/').pop() ?? path
const label = (text: Text, detail = ''): Label => ({ text, detail })
const stillHere = (list: AgentPet[], now: number) => list.filter(pet => pet.leaving === undefined || pet.leaving.until > now)
const stirFor = () => (STIR_SECONDS[0] + (STIR_SECONDS[1] - STIR_SECONDS[0]) * Math.random()) * 1000
// A reaction still showing that a new one waits for: one the pointer did gives way.
const holds = (live: Reaction | null, now: number) => live !== null && live.until > now && live.byTouch !== true

// What the pointer posted: the kinds of what it did, in order. Code sent it, so it is checked.
const pointerEvents = (data: unknown): string[] => {
  const events = (data as { events?: unknown } | null)?.events
  return Array.isArray(events) ? events.filter((one): one is string => typeof one === 'string') : []
}

const reactionTo = (poke: Exclude<Poke, 'ignore'>, missed: boolean, now: number): Reaction => {
  const until = now + REACTION_MS
  switch (poke) {
    case 'pet':
      return { mood: 'happy', label: label(missed ? 'missedYou' : 'petted'), until, byTouch: true }
    case 'wake':
      return { mood: 'happy', label: label('wakingUp'), until, byTouch: true }
    case 'rouse':
      return { mood: 'grumpy', label: label('rudeAwakening'), until, byTouch: true }
    case 'annoy':
      return { mood: 'grumpy', label: label('annoyed'), until: now + ANNOY_MS, byTouch: true }
  }
}

const describe = (e: ToolCallInput): Activity => {
  switch (e.tool) {
    case 'Bash':
      return { mood: 'running', label: label('running', short(e.command)) }
    case 'Edit':
    case 'Write':
      return { mood: 'writing', label: label('writing', basename(e.file_path)) }
    case 'Read':
      return { mood: 'reading', label: label('reading', basename(e.file_path)) }
    case 'Agent':
      return { mood: 'supervising', label: label('waitingForAgents') }
  }
  const tool = String(e.tool)
  return SEARCHERS.has(tool)
    ? { mood: 'searching', label: label('searching', tool) }
    : { mood: 'typing', label: label('using', short(tool, 24)) }
}

const callKey = (agentId: string | undefined, tool: string) => `${agentId ?? 'main'}:${tool}`

// The engine's words for a call the person said no to: there is no flag for it.
const isDenial = (ran: { isError?: boolean; result?: unknown }) =>
  ran.isError === true && typeof ran.result === 'string' && ran.result.includes("doesn't want to proceed")

const reason = (error: unknown) => (error instanceof Error ? error.message : String(error))

// The language and the pack are read once per module load: a settings change
// reloads the module, and with it these.
let choosing: Promise<Locale> | undefined
// Kept with the name it is for: a draw can ask before `session.start` has read the
// project's own pet, and the settings' pet must not stand in for it after.
let loading: { name: string; pack: Promise<Pack> } | undefined

function localeOf($: EngineInterface, choice: string) {
  choosing ??= (async () => {
    const settings = await $.settings.read()
    return pickLocale(choice, settings.language, await $.env.get('LANG'))
  })()
  return choosing
}

// The first pack found wins; a broken or missing one is why not, in words.
async function findPack($: EngineInterface, name: string, locale: Locale): Promise<Pack | string> {
  const home = (await $.env.get('HOME')) ?? (await $.env.get('USERPROFILE'))
  const paths = packPaths(name, home, $.plugin.root)
  let problem = say(locale, paths === undefined ? 'invalidName' : 'notFound', name)

  for (const path of paths ?? []) {
    let text: string
    try {
      text = await $.fs.read(path)
    } catch {
      continue
    }
    try {
      return parsePack(JSON.parse(text))
    } catch (error) {
      problem = `${path}: ${reason(error)}`
      break
    }
  }
  return problem
}

// A broken or missing pack falls back to the shipped default, and the toast says why.
async function readPack($: EngineInterface, name: string, locale: Locale): Promise<Pack> {
  const found = await findPack($, name, locale)
  if (typeof found !== 'string') return found
  const fallback = parsePack(JSON.parse(await $.fs.read(`${$.plugin.root}/pets/${DEFAULT_PET}.json`)))
  $.ui.toast(say(locale, 'fallback', found))
  return fallback
}

function packOf($: EngineInterface, name: string, locale: Locale) {
  if (loading?.name !== name) loading = { name, pack: readPack($, name, locale) }
  return loading.pack
}

// `/pet <name>` picks a project's own pet, kept by project root; `/pet default`
// goes back to the one in the settings.
const DEFAULT_ARG = 'default'

async function projectPets($: EngineInterface): Promise<Record<string, string>> {
  const kept = await $.store.get('projectPets')
  return typeof kept === 'object' && kept !== null && !Array.isArray(kept) ? (kept as Record<string, string>) : {}
}

// This session's project's pet, if one was picked.
async function projectPet($: EngineInterface) {
  try {
    const name = (await projectPets($))[await $.session.root()]
    return typeof name === 'string' ? name : undefined
  } catch {
    return undefined
  }
}

async function keepProjectPet($: EngineInterface, root: string, name: string | undefined) {
  const { [root]: _, ...others } = await projectPets($)
  await $.store.set('projectPets', name === undefined ? others : { ...others, [root]: name })
}

const hourOf = (now: number) => new Date(now).getHours()
const anniversary = (days: number): Label =>
  days === 7
    ? label('aWeekTogether')
    : days === 30
      ? label('aMonthTogether')
      : days === 365
        ? label('aYearTogether')
        : days % 365 === 0
          ? label('yearsTogether', String(days / 365))
          : label('daysTogether', String(days))

// Notes that the person is here now, and when they first met. Returns the visit
// before this one. With no store it remembers nothing, and holds nothing up.
async function remember($: EngineInterface, now: number) {
  try {
    const visit = asVisit(await $.store.get('visit'))
    await $.store.set('visit', { metAt: visit?.metAt ?? now, lastSeenAt: now })
    return visit
  } catch {
    return undefined
  }
}

// How the day's first sight of the person goes: an anniversary, missing them, or
// good morning. Checked when a session opens and on each prompt, so a session left
// open overnight still greets the morning. `before` is the visit before this one.
async function greet($: EngineInterface, now: number, before: Visit | undefined) {
  const hello = welcome(before, now, hourOf(now))
  if (hello === undefined) return
  const until = now + GREETING_MS
  const shown: Reaction =
    hello.kind === 'anniversary'
      ? { mood: 'celebrating', label: anniversary(hello.days), until: now + CELEBRATION_MS }
      : hello.kind === 'missedYou'
        ? { mood: 'happy', label: label('missedYou'), until }
        : { mood: 'waking', label: label('goodMorning'), until }
  await update($, reaction, () => shown)
}

// When the person came back from their last break, across every session: an hour
// with no prompt in any of them rests the pet. `before` is the visit before this one.
async function restedSince($: EngineInterface, now: number, before: Visit | undefined) {
  try {
    const kept = await $.store.get('restedAt')
    if (typeof kept === 'number' && before !== undefined && now - before.lastSeenAt < BREAK_MS) return kept
    await $.store.set('restedAt', now)
  } catch {
    // No store: rested as of now, as a session that remembers nothing.
  }
  return now
}

// Whether no session has said the late-night line yet tonight.
async function quietTonight($: EngineInterface, now: number) {
  try {
    return (await $.store.get('lateNight')) !== nightOf(now)
  } catch {
    return true
  }
}

async function saidTonight($: EngineInterface, now: number) {
  try {
    await $.store.set('lateNight', nightOf(now))
  } catch {
    // No store: this session alone keeps it.
  }
}

// The person is at the prompt: the day's welcome, and their rest, from the visit
// before, which it returns.
async function atThePrompt($: EngineInterface, now: number) {
  const before = await remember($, now)
  await greet($, now, before)
  const since = await restedSince($, now, before)
  await update($, restedAt, () => since)
  return before
}

// "Together for 12 days", for /pet; nothing when it has no memory of the person.
async function together($: EngineInterface, locale: Locale) {
  try {
    const visit = asVisit(await $.store.get('visit'))
    if (visit === undefined) return ''
    const days = daysBetween(visit.metAt, await $.clock.now())
    const said = days === 0 ? say(locale, 'justMet') : days === 1 ? say(locale, 'togetherADay') : say(locale, 'togetherDays', String(days))
    return ` ${said.charAt(0).toUpperCase()}${said.slice(1)}.`
  } catch {
    return ''
  }
}

// What it learned of the person's taste, shared by every session, and the seed that
// fixes its whims and tempers (and, in the experiment, which days are lively). The
// first load picks the seed. With no store it learns nothing and lives as it always did.
type Learning = { seed: number; bandit: Bandit }

async function loadLearning($: EngineInterface): Promise<Learning | undefined> {
  try {
    const kept = (await $.store.get('learning')) as { seed?: unknown; bandit?: unknown } | undefined
    if (typeof kept?.seed === 'number') return { seed: kept.seed, bandit: asBandit(kept.bandit) }
    await $.store.set('learning', { seed: Math.floor(Math.random() * 2 ** 32), bandit: {} })
    // Read back: a session starting at the same moment may have set its own seed last.
    const settled = (await $.store.get('learning')) as { seed?: unknown; bandit?: unknown } | undefined
    return typeof settled?.seed === 'number' ? { seed: settled.seed, bandit: asBandit(settled.bandit) } : undefined
  } catch {
    return undefined
  }
}

// The experiment's log, a line per event, where the person can read and delete it:
// a file per session, so sessions open at once never write over each other's lines.
// With no experiment there is no file name, and nothing is logged.
async function logPath($: EngineInterface, name: string) {
  const home = (await $.env.get('HOME')) ?? (await $.env.get('USERPROFILE'))
  return home === undefined ? undefined : `${home}/.claude/pixel-pets/learning/${name}.jsonl`
}

// No append in $.fs: the session's file is read and written again, which a
// session's few hundred lines afford.
async function appendLog($: EngineInterface, name: string | undefined, lines: string[]) {
  const path = name === undefined ? undefined : await logPath($, name)
  if (path === undefined || lines.length === 0) return
  // A read that fails stops the write, rather than write the lines over what was there.
  const text = (await $.fs.exists(path)) ? await $.fs.read(path) : ''
  await $.fs.write(path, text + lines.map(line => `${line}\n`).join(''))
}

// What is past its minute counts for the bandit, read again from the store as
// another session may have learned meanwhile, and goes in the log.
// ponytail: two sessions settling at the same moment may lose one's update; take a
// lock in the store if the log shows tallies short of its lines.
// With no store it learns nothing, but the log still gets its lines.
async function keepLearned($: EngineInterface, name: string | undefined, done: Shown[]) {
  let learned: Learning | undefined
  try {
    const kept = await loadLearning($)
    if (kept !== undefined) {
      learned = { ...kept, bandit: settle(kept.bandit, done, Infinity).bandit }
      await $.store.set('learning', learned)
    }
  } catch {
    learned = undefined
  }
  await appendLog($, name, done.map(logLine))
  return learned
}

// How unusual a prompt's moment is, before it becomes a little more familiar; and
// how many of the person's moments it knew by then.
async function noteMoment($: EngineInterface, name: string | undefined, code: number[], now: number, seed: number) {
  const { seen: known, cells } = asFamiliarity(await $.store.get('familiar'))
  const news = novelty(cells, code, now, FAMILIAR_HALF_LIFE_MS)
  see(cells, code, now, FAMILIAR_HALF_LIFE_MS)
  await $.store.set('familiar', { seen: known + 1, cells })
  const line = { kind: 'novelty', at: now, arm: armOf(seed, now), temper: temperOf(seed, now), daypart: daypartOf(hourOf(now)), novelty: news }
  await appendLog($, name, [JSON.stringify(line)])
  return { news, known }
}

async function loadRhythm($: EngineInterface) {
  try {
    return asRhythm(await $.store.get('rhythm'))
  } catch {
    return {}
  }
}

// The person turned up: one more arrival at this half hour of the day.
async function noteArrival($: EngineInterface, name: string | undefined, now: number) {
  const rhythm = arrived(await loadRhythm($), now)
  await $.store.set('rhythm', rhythm)
  await appendLog($, name, [JSON.stringify({ kind: 'arrival', at: now })])
  return rhythm
}

// Clears the override only if it is still the one this hook set.
async function release($: EngineInterface, mood: Mood) {
  await update($, override, current => (current?.mood === mood ? null : current))
}

export const register: Register = (on, options) => {
  // The picker names a shipped pet, or `custom` for the person's own pack named in `customPet`.
  const picked = options.pet === 'custom' ? options.customPet : options.pet
  const configured = typeof picked === 'string' && picked !== '' ? picked : DEFAULT_PET
  // The project's own pet, if `/pet <name>` picked one, else the settings'.
  let petName = configured
  // The pack the frame clock plays, the clock, and a way to start it again at another pack's pace.
  let playing: Pack | undefined
  let timer: Timer | undefined
  let restartClock = () => {}
  const language = typeof options.language === 'string' ? options.language : 'auto'
  // false: the band is the stage alone, without Claude's line above it.
  const showsLine = options.labelLine !== false
  // false: each agent is its mini pet alone, without its name and words under it.
  const showsAgentLabels = options.agentLabels !== false
  // On (the default), the pet lives by its own whims and what it learns of the
  // person; off, it lives as it always did, and keeps nothing of them.
  const isAlive = options.lively !== false
  // The experiment: lively and usual days in turn, each logged, to compare them.
  const experiments = isAlive && options.learningExperiment === true
  let learning: Learning | undefined
  // When the person usually turns up; what it did lately, the latest first; and
  // when it last found a moment odd.
  let rhythm: Rhythm = {}
  let lately: string[] = []
  let oddAt = 0
  // Loaded once, at session.start or, after a reload (a settings change), at the next draw.
  let hasLoaded = false
  // Today it lives by what it learned and its whims, rather than as it always did:
  // every day, but in the experiment only on its lively days.
  const isLively = (now: number) => learning !== undefined && (!experiments || armOf(learning.seed, now) === 'learned')
  // Away a while and about to turn up, as they usually do now: it waits for them,
  // until it has greeted them or run out of patience. `waitingFrom` is when it began
  // to wait through the pause that began at its `idleSince`.
  let waitingFrom: { idleSince: number; at: number } | undefined
  const waitsFor = (idleSince: number | null, now: number) => {
    if (idleSince === null || !isLively(now) || now - idleSince < AWAY_MS || !expects(rhythm, now) || wokeForThem(idleSince)) return false
    if (waitingFrom?.idleSince !== idleSince) waitingFrom = { idleSince, at: now }
    return now - waitingFrom.at < PATIENCE_MS
  }
  // Activities shown in the last minute, waiting for a pet; and the learned pick last made.
  let recent: Shown[] = []
  let lastPick: { activity: string; propensity: number } | undefined
  // The store and the log are written one change at a time, in order, the log to
  // a file of this session's own: its day, and a few random letters.
  let writing = Promise.resolve()
  let logName: string | undefined
  const logNameAt = (now: number) =>
    experiments ? (logName ??= `${new Date(now).toISOString().slice(0, 10)}-${Math.random().toString(36).slice(2, 8)}`) : undefined
  const awakeMs = (typeof options.awakeMinutes === 'number' && options.awakeMinutes >= 0 ? options.awakeMinutes : 1) * 60_000
  let frame = 0
  // What the main pet is playing and where it stands, between draws; a reload starts them fresh.
  let motion: Motion | undefined
  // Where it stands and each agent's side, kept so none hops over when another leaves.
  let stage: Stage = EMPTY_STAGE
  // A full redraw costs Claude Code far more than repainting a Raster, and every
  // open session pays it. The band keeps how to play itself a tick on: the clock
  // plays it, repaints the agents' Rasters whose cells changed, leaves the main
  // pet's frame for its Client to ask for, and redraws in full only when anything
  // else would change (a step, its words), when something it shows runs out, and
  // now and then for what changes with time alone. While the pet is hidden the
  // clock redraws nothing, as showing it again redraws.
  let scene: Scene | null = null
  // The main pet's frame its Client has, by `Shot.main`.
  let sentMain: string | null = null
  // What the pointer has done to it, and whether it was looking back as last drawn.
  let touched: Touch = untouched
  let gazing = false
  // With no Client drawn, no `leave` comes: the pointer counts as gone.
  const letGo = () => {
    touched = leave(touched)
    gazing = false
  }
  let isOff = false
  // The tool call running for each agent and tool, so a permission prompt (which
  // names only those) finds the call it is for; and the calls that asked.
  // ponytail: two same-named calls of one agent at once share a key; the later wins.
  const openCalls = new Map<string, string>()
  const asked = new Set<string>()
  // Only a session with a person at the prompt counts as seeing them: a `claude -p`
  // run must not spend the day's welcome.
  let isInteractive = false
  // What it said lately and what it is saying now; a reload starts them fresh.
  let speaker: Speaker = quiet
  let saying: { text: string; until: number } | null = null
  // Since when the main loop has run no tool (null while one runs), and its tools and reads this turn.
  let thinkingSince: number | null = null
  let toolsThisTurn = 0
  let readsThisTurn = 0
  // An agent finished since the pet last cheered: the turn that reports it is worth a cheer.
  let agentsDone = false
  // The night it last said it was getting late, by its evening's date.
  let saidNight: string | null = null
  // What it wants, from the first draw on, and what the band showed last, which is
  // what it has been up to since; plus until when it is up on its own.
  let drives: Drives | undefined
  // How the pet is made, from its pack once the band has drawn it.
  let traits: Traits = USUAL
  let lastState: State = 'awake'
  let stirredUntil = 0
  // The way it faced as the action it plays began, kept until it ends.
  let heldFacing: Held
  // When it last woke up glad at the person's first key after a long while away,
  // and whether that was since it went idle at `idleSince`.
  let gladAt: number | null = null
  // When it talks in its sleep next; null until it naps after a turn. Up on its own
  // for a moment, it keeps the time, or a long pause would leave it no time to dream.
  let dreamAt: number | null = null
  const wokeForThem = (idleSince: number | null) => gladAt !== null && idleSince !== null && gladAt >= idleSince
  // Busy with an activity, it is up whatever the time: sleep would cut it short.
  const isPlaying = () => activityIn(motion, frame) !== undefined
  // It dozes off sooner at night, and when it runs low on energy; not drawn yet, it is rested.
  const howLongAwake = (now: number) =>
    (isNight(hourOf(now)) ? awakeMs / 2 : awakeMs) * (drives === undefined ? 1 : alertness(drift(drives, now, lastState, traits)))
  // Dozed off a while back and in a deep spell of the pause that began at `idleSince`, and
  // not up on its own nor glad to see them.
  const isFastAsleep = (idleSince: number | null, now: number) =>
    idleSince !== null &&
    now - idleSince > howLongAwake(now) + FIRST_NAP_MS &&
    now >= stirredUntil &&
    !isPlaying() &&
    isDeep(idleSince, now - idleSince) &&
    !wokeForThem(idleSince)
  // Long idle, it naps, unless up on its own or busy with an activity; `isDozing`
  // also unless bored enough to get up.
  const isDrowsy = (idleSince: number | null, now: number) => {
    const awakeFor = howLongAwake(now)
    // Unknown idle time (nothing has run yet) counts as a plain nap.
    const idleFor = idleSince === null ? awakeFor + 1 : now - idleSince
    return idleFor > awakeFor && now >= stirredUntil && !isPlaying()
  }
  const isDozing = (idleSince: number | null, now: number) =>
    isDrowsy(idleSince, now) && !(drives !== undefined && stirs(drift(drives, now, lastState, traits)))
  // Brings the drives up to `now` before `change` touches them.
  const touch = (now: number, change: (settled: Drives) => Drives) => {
    if (drives !== undefined) drives = change(drift(drives, now, lastState, traits))
  }

  // Says the line for `situation`, unless it spoke too lately or already did this turn.
  const speak = (situation: Situation, now: number, pack: Pack, locale: Locale) => {
    if (!maySpeak(speaker, situation, now)) return false
    speaker = spoke(speaker, situation, now)
    saying = { text: lineFor(pack.speech, locale.code, situation, say(locale, situation), Math.random), until: now + SPEECH_MS }
    return true
  }

  on('session.start', async ($, e, next) => {
    const locale = await localeOf($, language)
    await $.command.register({ name: 'pet', description: say(locale, 'commandDescription'), argumentHint: '[name | default]' })
    petName = (await projectPet($)) ?? configured
    playing = await packOf($, petName, locale)
    if (isAlive && !hasLoaded) {
      hasLoaded = true
      learning = await loadLearning($)
      rhythm = await loadRhythm($)
    }
    const now = await $.clock.now()
    await update($, lastActiveAt, () => now)
    const tick = () => {
      const pack = playing
      frame += 1
      if (isOff || pack === undefined) return
      const last = scene
      const every = pack.fps * (last?.isAsleep === true ? REDRAW_ASLEEP_S : REDRAW_AWAKE_S)
      // With no stage of its own drawn (a survey, or a line of text), there is nothing to play.
      if (last === null) {
        if (frame % every === 0) $.ui.invalidate('ui.render')
        return
      }
      if (frame % every === 0 || frame >= last.redrawAt) {
        $.ui.invalidate('ui.render')
        return
      }
      const shot = last.play()
      if (shot.layout !== last.shot.layout) {
        $.ui.invalidate('ui.render')
        return
      }
      // The agents' Rasters are repainted here; the main pet's Client asks for its frame.
      const changed = Object.entries(shot.rasters).filter(([key, cells]) => last.shot.rasters[key] !== cells)
      last.shot = shot
      if (changed.length === 0) return
      // Refused when the band is no longer last as it was: redraw it in full.
      void Promise.all(changed.map(([key, cells]) => $.ui.blit({ requestId: last.requestId, key, cells })))
        .then(done => done.some(one => one.deny !== undefined))
        .catch(() => true)
        .then(refused => {
          if (refused) $.ui.invalidate('ui.render')
        })
    }
    restartClock = () => {
      timer?.cancel()
      timer = $.clock.every(Math.round(1000 / (playing?.fps ?? 4)), tick)
    }
    restartClock()
    isInteractive = e.isInteractive
    if (isInteractive) {
      const before = await atThePrompt($, now)
      if (learning !== undefined && (before === undefined || now - before.lastSeenAt >= AWAY_MS)) {
        const name = logNameAt(now)
        writing = writing.then(() => noteArrival($, name, now).then(kept => void (rhythm = kept))).catch(() => {})
      }
    } else await update($, restedAt, at => at ?? now)
    return next(e)
  })

  // The main pet's Client hands over what the pointer did each tick, and asks for
  // its frame: it gets the one the clock played last, when it has not had it yet.
  on('ui.message', async ($, e, next) => {
    if (e.element !== 'touch') return next(e)
    const now = await $.clock.now()
    const events = pointerEvents(e.data)
    // How a click finds it: at work or watching agents it is awake whatever the time.
    let sleep: Sleep = 'awake'
    if (events.includes('down')) {
      const idleSince = await read($, lastActiveAt)
      const isBusy = (await read($, turnStartedAt)) !== null || stillHere(await read($, agents), now).some(one => one.leaving === undefined)
      // Up waiting for them, it is awake whatever the time.
      sleep = isBusy || waitsFor(idleSince, now) ? 'awake' : isFastAsleep(idleSince, now) ? 'deep' : isDozing(idleSince, now) ? 'dozing' : 'awake'
    }
    let poke: Poke = 'ignore'
    for (const event of events) {
      if (event === 'down') {
        const pressed = press(touched, now, sleep)
        touched = pressed.touch
        if (pressed.poke !== 'ignore') poke = pressed.poke
      } else if (event === 'leave') touched = leave(touched)
      else if (event === 'enter' || event === 'move') touched = hover(touched, now)
    }
    if (learning !== undefined && poke === 'pet') recent = petted(recent, now)
    if (learning !== undefined && poke === 'annoy') {
      recent = annoyed(recent, now)
      const line = JSON.stringify({ kind: 'annoy', at: now, arm: isLively(now) ? 'learned' : 'hand' })
      const name = logNameAt(now)
      writing = writing.then(() => appendLog($, name, [line])).catch(() => {})
    }
    if (poke !== 'ignore') {
      // Any touch is the person being there; woken glad, it stays up a while.
      let missed = false
      touch(now, settled => {
        missed = misses(settled)
        return seen(settled)
      })
      if (poke === 'wake') stirredUntil = now + stirFor()
      const shown = reactionTo(poke, missed, now)
      await update($, reaction, live => (holds(live, now) ? live : shown))
      $.ui.invalidate('ui.render')
    }
    if (gazes(touched, now) !== gazing) {
      gazing = !gazing
      $.ui.invalidate('ui.render')
    }
    const shot = scene?.shot
    if (shot === undefined || shot.main === sentMain) return {}
    sentMain = shot.main
    return { props: shot.art }
  })

  on('command.run', { command: 'pet' }, async ($, e) => {
    const locale = await localeOf($, language)
    const asked = (e.args ?? '').trim()
    if (asked === '') {
      const hidden = await update($, isHidden, value => !value)
      return { text: `${say(locale, hidden ? 'hidden' : 'shown')}${await together($, locale)}` }
    }

    // A pet asked by name is tried before it is kept: one that does not load leaves
    // things as they were. `default` always lets go of the project's own, even when
    // the settings' pet is broken and falls back to the shipped one.
    const isDefault = asked === DEFAULT_ARG
    const name = isDefault ? configured : asked
    const found = isDefault ? await readPack($, name, locale) : await findPack($, name, locale)
    if (typeof found === 'string') return { text: say(locale, 'projectPetFailed', found) }
    try {
      await keepProjectPet($, await $.session.root(), isDefault ? undefined : name)
    } catch {
      // No store: the pet changes for this session alone.
    }
    petName = name
    loading = { name, pack: Promise.resolve(found) }
    playing = found
    motion = undefined
    scene = null
    restartClock()
    $.ui.invalidate('ui.render')
    return { text: say(locale, isDefault ? 'projectPetDefault' : 'projectPet', name) }
  })

  // The pet looks at the prompt while the person types in it, glad at the first key
  // after a long while away, unless a turn or something else is showing.
  on('prompt.edit', async ($, e, next) => {
    const now = await $.clock.now()
    await update($, typingAt, () => now)
    // Waiting up for them, it is glad they came as it thought they would.
    const waited = waitsFor(await read($, lastActiveAt), now)
    let missed = false
    touch(now, settled => {
      missed = misses(settled)
      return seen(settled)
    })
    if ((missed || waited) && (await read($, turnStartedAt)) === null) {
      gladAt = now
      const glad: Reaction = { mood: 'happy', label: label(waited ? 'thereYouAre' : 'missedYou'), until: now + REACTION_MS }
      await update($, reaction, live => (holds(live, now) ? live : glad))
    }
    return next(e)
  }).catch(($, e, next) => next(e))

  // What is still waiting for a pet when the session ends counts as it stands: no
  // pet can come any more. The writes left are seen through before it goes.
  on('session.end', async ($, e, next) => {
    if (learning !== undefined && recent.length > 0) {
      const done = recent
      recent = []
      const name = logNameAt(await $.clock.now())
      writing = writing.then(() => keepLearned($, name, done).then(() => {})).catch(() => {})
    }
    await writing
    return next(e)
  }).catch(($, e, next) => next(e))

  // Only a pet in deep sleep is startled awake; a dozing one just starts thinking,
  // one keeping an eye on background agents was awake all along, and one glad to
  // see the person woke up already.
  on('prompt.submit', async ($, e, next) => {
    const now = await $.clock.now()
    const idleSince = await read($, lastActiveAt)
    const busySince = await read($, turnStartedAt)
    const isSupervising = stillHere(await read($, agents), now).some(one => one.leaving === undefined)
    // Up waiting for them, it is no more asleep than when they type.
    if (busySince === null && !isSupervising && isFastAsleep(idleSince, now) && !waitsFor(idleSince, now)) {
      await update($, reaction, (): Reaction => ({ mood: 'waking', label: label('wakingUp'), until: now + WAKING_MS }))
    }
    touch(now, seen)
    // How unusual this moment is. Once it knows the person's moments well, an odd
    // one gets a curious look on a lively day, an hour apart at most.
    // A `claude -p` run is no moment of the person's.
    if (learning !== undefined && isInteractive) {
      const { seed } = learning
      const code = momentCode(hourOf(now), idleSince === null ? 0 : (now - idleSince) / 60_000, toolsThisTurn)
      const name = logNameAt(now)
      const noted = writing.then(() => noteMoment($, name, code, now, seed))
      writing = noted.then(
        () => {},
        () => {},
      )
      const moment = await noted.catch(() => undefined)
      if (moment !== undefined && isLively(now) && moment.known >= KNOWS && moment.news >= ODD && now - oddAt >= ODD_GAP_MS) {
        oddAt = now
        const curious: Reaction = { mood: 'watching', label: label('somethingNew'), until: now + REACTION_MS }
        await update($, reaction, live => (holds(live, now) ? live : curious))
      }
    }
    if (isInteractive) {
      const before = await atThePrompt($, now)
      // Away a while: they just turned up, and when is worth remembering.
      const isArrival = (before === undefined || now - before.lastSeenAt >= AWAY_MS) && (idleSince === null || now - idleSince >= AWAY_MS)
      if (learning !== undefined && isArrival) {
        const name = logNameAt(now)
        writing = writing.then(() => noteArrival($, name, now).then(kept => void (rhythm = kept))).catch(() => {})
      }
    }
    // Once a night across every session: the first to see the person late says it.
    const tonight = nightOf(now)
    if (isNight(hourOf(now)) && saidNight !== tonight) {
      if (await quietTonight($, now)) {
        const locale = await localeOf($, language)
        if (speak('lateNight', now, await packOf($, petName, locale), locale)) {
          saidNight = tonight
          await saidTonight($, now)
        }
      } else saidNight = tonight
    }
    return next(e)
  }).catch(($, e, next) => next(e))

  on('turn.start', async ($, e, next) => {
    const now = await $.clock.now()
    await update($, activity, (): Activity => ({ mood: 'thinking', label: label('thinking') }))
    await update($, turnStartedAt, () => now)
    speaker = { ...speaker, saidThisTurn: [] }
    touch(now, engaged)
    thinkingSince = now
    toolsThisTurn = 0
    readsThisTurn = 0
    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    const now = await $.clock.now()
    const isBad = e.reason === 'error' || e.reason === 'refusal'

    if (e.agentId !== undefined) {
      const id = e.agentId
      const leaving = { mood: (isBad || e.isAborted ? 'sad' : 'happy') as MiniMood, until: now + LEAVING_MS }
      await update($, agents, list => stillHere(list, now).map(pet => (pet.id === id ? { ...pet, leaving } : pet)))
      await update($, lastActiveAt, () => now)
      agentsDone = true
      return next(e)
    }

    if (!e.isAborted) await update($, feelings, felt => feel(felt, isBad ? 'turnFailed' : 'turnOk', now))
    const startedAt = await read($, turnStartedAt)
    const tookLong = startedAt !== null && now - startedAt >= LONG_WIN_MS
    const agentsLeft = stillHere(await read($, agents), now).filter(one => one.leaving === undefined).length
    const cheered = cheer({ tookLong, tools: toolsThisTurn, agentsDone, agentsLeft }, Math.random)
    if (agentsLeft === 0) agentsDone = false
    const until = now + REACTION_MS
    // An interrupted turn earns no reaction, and one still showing (a thanks, a
    // "fine, I won't" after a denied permission, a failure) is left to finish.
    // A failure always shows; a turn that went well only sometimes cheers.
    const live = await read($, reaction)
    if (!e.isAborted && !holds(live, now) && (isBad || cheered !== null)) {
      await update($, reaction, (): Reaction =>
        isBad
          ? { mood: 'sad', label: label('wentWrong'), until }
          : cheered === 'celebrating'
            ? { mood: 'celebrating', label: label('phew'), until: now + CELEBRATION_MS }
            : { mood: 'happy', label: label('done'), until },
      )
    }
    await update($, override, () => null)
    await update($, turnStartedAt, () => null)
    await update($, lastActiveAt, () => now)
    return next(e)
  })

  on('agent.spawn', async ($, e, next) => {
    const started = await next(e)
    const id = 'agentId' in started ? started.agentId : undefined
    if (id !== undefined) {
      const now = await $.clock.now()
      await update($, agents, list => {
        const color = AGENT_COLORS[list.length % AGENT_COLORS.length] ?? 0xffffff
        const pet: AgentPet = { id, toolUseId: e.tool_use_id, type: e.subagentType, label: label('thinking'), color }
        return [...stillHere(list, now), pet]
      })
      const working = stillHere(await read($, agents), now).filter(one => one.leaving === undefined)
      if (working.length >= MANY_AGENTS) {
        const locale = await localeOf($, language)
        speak('manyAgents', now, await packOf($, petName, locale), locale)
      }
    }
    return started
  }).catch(($, e, next) => next(e))

  on('tool.call', async ($, e, next) => {
    const now = describe(e)
    const agentId = e.agentId

    if (agentId === undefined) {
      await update($, activity, () => now)
    } else {
      await update($, agents, list => list.map(pet => (pet.id === agentId ? { ...pet, label: now.label } : pet)))
    }

    if (agentId === undefined) {
      thinkingSince = null
      toolsThisTurn += 1
    }
    const key = callKey(agentId, String(e.tool))
    openCalls.set(key, e.tool_use_id)
    let ran: Awaited<ReturnType<typeof next>>
    let wasAsked = false
    try {
      ran = await next(e)
    } finally {
      if (openCalls.get(key) === e.tool_use_id) openCalls.delete(key)
      wasAsked = asked.delete(e.tool_use_id)
    }

    // A background agent's tool call returns at once; its pet leaves on its own
    // turn.complete. Only a spawn that failed is dropped here.
    if (e.tool === 'Agent' && ran.isError === true) {
      await update($, agents, list => list.filter(pet => pet.toolUseId !== e.tool_use_id))
    }
    const at = await $.clock.now()
    const until = at + REACTION_MS
    if (agentId === undefined) {
      thinkingSince = at
      if (e.tool === 'Read' && (readsThisTurn += 1) === MANY_READS) {
        const locale = await localeOf($, language)
        speak('manyReads', at, await packOf($, petName, locale), locale)
      }
    }
    if (wasAsked) {
      // The person answered a permission prompt: thanks for a yes, fine for a no.
      const thanked: Reaction = isDenial(ran)
        ? { mood: 'sad', label: label('denied'), until }
        : { mood: 'happy', label: label('thanks'), until }
      await update($, reaction, () => thanked)
    } else if (agentId === undefined && ran.isError === true) {
      // "failed: npm test", or the tool's name when the action has no detail.
      const failed = label('failed', short(now.label.detail || String(e.tool), 24))
      await update($, reaction, (): Reaction => ({ mood: 'sad', label: failed, until }))
      await update($, feelings, felt => feel(felt, 'toolFailed', at))
    }
    return ran
  }).catch(($, e, next) => next(e))

  // The band is hidden while a permission dialog is open (and `$.ui.notice` does
  // not show under the terminal's), so the pet only marks the call that asked;
  // tool.call reacts once the person has answered.
  on('classic.PermissionRequest', async ($, e, next) => {
    const id = openCalls.get(callKey(e.agent_id, e.tool_name))
    if (id !== undefined) asked.add(id)
    return next(e)
  }).catch(($, e, next) => next(e))

  on('session.compact', async ($, e, next) => {
    await update($, override, (): Activity => ({ mood: 'compacting', label: label('compacting') }))
    try {
      return await next(e)
    } finally {
      await release($, 'compacting')
    }
  }).catch(($, e, next) => next(e))

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    scene = null
    isOff = await read($, isHidden)
    if (e.props.hasSurvey || isOff) {
      letGo()
      return next(e)
    }

    const locale = await localeOf($, language)
    const pack = await packOf($, petName, locale)
    const now = await $.clock.now()
    const busy = await read($, override)
    const flash = await read($, reaction)
    const doing = await read($, activity)
    const startedAt = await read($, turnStartedAt)
    const idleSince = await read($, lastActiveAt)
    const typedAt = await read($, typingAt)
    const list = stillHere(await read($, agents), now)
    const words = (one: Label) => say(locale, one.text, one.detail)
    // ponytail: the drives move only when the band is drawn, so a band hidden by /pet
    // counts all that time as what it last showed; give them a clock of their own if that skews them.
    if (isAlive && !hasLoaded) {
      hasLoaded = true
      learning = await loadLearning($)
      rhythm = await loadRhythm($)
    }
    // On a lively day it wakes up in a temper: a little more playful, lazy, clingy or curious.
    traits = learning !== undefined && isLively(now) ? tempered(pack.personality, temperOf(learning.seed, now)) : pack.personality
    drives = drives === undefined ? rested(now) : drift(drives, now, lastState, traits)
    // What is past its minute counts for what it learned, and goes in the log.
    const done = recent.filter(one => now - one.at > CREDIT_MS)
    if (done.length > 0) {
      recent = recent.filter(one => now - one.at <= CREDIT_MS)
      const name = logNameAt(now)
      writing = writing
        .then(() => keepLearned($, name, done))
        .then(kept => {
          if (kept !== undefined) learning = kept
        })
        .catch(() => {})
    }

    let shown: Activity
    let extra = ''
    const isFlashing = flash !== null && flash.until > now
    // Petted at work, it shows it but leaves Claude's line be.
    const isPettedAtWork = isFlashing && flash.byTouch === true && e.props.isWorking
    if (busy !== null) {
      shown = busy
    } else if (isFlashing && !isPettedAtWork) {
      shown = flash
    } else if (e.props.isWorking) {
      const elapsed = startedAt === null ? 0 : now - startedAt
      const isLong = elapsed > LONG_TURN_MS && PATIENT.includes(doing.mood)
      if (thinkingSince !== null && now - thinkingSince >= LONG_THINK_MS) speak('longThink', now, pack, locale)
      // A turn that only thinks while agents still run is waiting on them.
      const current: Activity =
        doing.mood === 'thinking' && list.some(one => one.leaving === undefined)
          ? { mood: 'supervising', label: label('waitingForAgents') }
          : doing
      shown = isPettedAtWork ? { ...current, mood: flash.mood } : isLong ? { ...current, mood: 'sweating' } : current
      if (isLong) extra = ` · ${Math.floor(elapsed / 60_000)}m`
    } else {
      const hour = hourOf(now)
      const isTyping = typedAt !== null && now - typedAt < TYPING_MS
      // Once glad to see them it only dozes, so the prompt it sends does not startle it.
      const isDeeplyAsleep = isFastAsleep(idleSince, now)
      // Fast asleep it does not look up.
      if (isTyping && !isDeeplyAsleep) shown = { mood: 'watching', label: label('watching') }
      // Background agents still at work: it keeps an eye on them rather than dozing off.
      else if (list.some(one => one.leaving === undefined)) shown = { mood: 'supervising', label: label('waitingForAgents') }
      // About when they usually turn up, it gets up and watches the prompt for them.
      else if (waitsFor(idleSince, now)) shown = { mood: 'watching', label: label('waitingForYou') }
      else if (isDeeplyAsleep) shown = { mood: 'deepSleep', label: label('deepSleep') }
      else if (isDozing(idleSince, now)) shown = asleep
      else {
        // Bored in a nap, it gets up for a while on its own.
        if (isDrowsy(idleSince, now)) {
          stirredUntil = now + stirFor()
          drives = stirred(drives)
          speak('bored', now, pack, locale)
        }
        const felt = idleMood(await read($, feelings), now, await read($, restedAt), hour)
        // A pointer resting on it gets a look back.
        if (gazes(touched, now)) shown = { mood: 'watching', label: label('lookingAtYou') }
        else shown = felt === undefined ? { mood: 'idle', label: label('idle') } : { mood: felt, label: label(felt) }
      }
    }

    lastState = shown.mood === 'sleeping' || shown.mood === 'deepSleep' ? 'asleep' : e.props.isWorking ? 'working' : 'awake'
    // Asleep, it talks in its sleep now and then, as rarely as it speaks at all.
    const dreamGap = () => (DREAM_MINUTES[0] + (DREAM_MINUTES[1] - DREAM_MINUTES[0]) * Math.random()) * 60_000
    if (lastState === 'working') dreamAt = null
    else if (lastState === 'asleep') {
      if (dreamAt === null) dreamAt = now + dreamGap()
      else if (now >= dreamAt) {
        speak('dreaming', now, pack, locale)
        dreamAt = now + dreamGap()
      }
    }

    const miniSize = sizeOf(pack.mini?.working[0] ?? [])
    const slot = showsAgentLabels ? Math.max(miniSize.columns, AGENT_SLOT) : miniSize.columns
    const petColumns = sizeOf(pack.moods.sleeping[0] ?? []).columns
    // As many agents as fit beside the pet; the rest are a "+N" that needs room too.
    // A pack with no mini pets shows its agents only by its own mood.
    const room = e.props.bodyColumns - petColumns - 2
    const fits = (count: number) => count * (slot + 1) + (count < list.length ? OVERFLOW_COLUMNS : 0) <= room
    let shownAgents = pack.mini === null ? 0 : Math.min(list.length, MAX_AGENTS)
    while (shownAgents > 0 && !fits(shownAgents)) shownAgents -= 1
    const visible = list.slice(0, shownAgents)
    const hidden = pack.mini === null ? 0 : list.length - visible.length
    const agentWords = (one: AgentPet) =>
      one.leaving === undefined ? words(one.label) : say(locale, one.leaving.mood === 'sad' ? 'wentWrong' : 'done')

    // Every frame is one size, so the sleeping one tells whether the stage fits, tall and wide.
    // A line of text has no stage, and must not move the pet on the one that has.
    const mainSize = sizeOf(pack.moods.sleeping[0] ?? [])
    if (e.surface !== 'terminal' || e.props.maxRows < mainSize.rows + (showsLine ? 1 : 0) || e.props.bodyColumns < mainSize.columns) {
      letGo()
      const { Text } = $.ui.resolve(e)
      const others = list.map(one => ` · ${one.type}: ${agentWords(one)}`).join('')
      return <Text dimColor>🐾 Claude: {words(shown.label)}{extra}{others}</Text>
    }

    // It only strolls alone; with agents around they gather on both sides, and when
    // they do not fit where it stands it hurries off to make room.
    // A proud pet struts about too; a sleepy, tired, worried or grumpy one stays put.
    const isRestless = shown.mood === 'idle' || shown.mood === 'proud'
    const width = slot + 1
    const extraColumns = hidden > 0 ? OVERFLOW_COLUMNS : 0
    // A pet that draws no walking but a teleport gets about by vanishing and appearing.
    const teleport = pack.walks ? null : pack.teleport
    const pace = paceOf(drives)
    const urge = urgeOf(drives)
    // A line it says takes Claude's line for a moment, unless a reaction or a mood that
    // must show is on it.
    // With no line there is nowhere to say it.
    const isQuoting = showsLine && saying !== null && saying.until > now && busy === null && !(flash !== null && flash.until > now)

    // Moves the pet and its agents one tick on from where the last draw or tick left
    // them. Safe to call again on the same tick: it shows the same.
    const play = () => {
      const onStage = moveOnStage(stage, {
        tick: frame,
        room,
        fps: pack.fps,
        random: Math.random,
        pace,
        walks: pack.walks,
        teleport: teleport === null ? null : { vanish: teleport.vanish.length, appear: teleport.appear.length },
        agents: visible.map(one => one.id),
        width,
        extra: extraColumns,
        // Busy with an activity it stays put: a step would cut it short.
        wants: placed =>
          visible.length > 0 ? { go: placed.x } : list.length === 0 && isRestless && activityIn(motion, frame) === undefined ? 'wander' : 'stay',
      })
      stage = onStage.stage
      const { drawn, drawnCount, standX, blinking } = onStage
      const blinkFrame = teleport === null || blinking === undefined ? undefined : teleport[blinking.phase][blinking.at]
      const showsMore = standX === onStage.placed.x && hidden > 0
      const isOnTheMove = onStage.moving || blinkFrame !== undefined
      const isStrolling = isOnTheMove && onStage.wants === 'wander'
      // A teleport is its walk: what falls due meanwhile waits for it to land.
      const mood: Mood = (pack.walks && onStage.moving) || blinkFrame !== undefined ? 'walking' : shown.mood
      const labelShown = isStrolling ? label('strolling') : shown.label

      // On a lively day it picks the activity by its whims and what earned pets at this time of day.
      const known = learning
      const arm = known === undefined ? undefined : isLively(now) ? 'learned' : 'hand'
      const daypart = daypartOf(hourOf(now))
      const choose =
        known !== undefined && arm === 'learned'
          ? (activities: string[]) =>
              (lastPick = pickFor({ bandit: known.bandit, seed: known.seed, pet: pack.name, daypart, activities, lately }, now, Math.random)).activity
          : undefined
      const before = motion?.once
      const moved = step(pack, motion, mood, frame, Math.random, urge, choose)
      const begun = moved.motion.once
      if (arm !== undefined && begun !== before && begun?.activity !== undefined) {
        const propensity = arm === 'learned' && lastPick?.activity === begun.activity ? lastPick.propensity : null
        recent = [...recent, { at: now, arm, daypart, pet: pack.name, activity: begun.activity, propensity, petted: 0, annoyed: false }]
        lately = [begun.activity, ...lately].slice(0, 5)
      }
      motion = moved.motion
      // Busy with an activity, the line says what, in its language or else in English.
      const pastime = pack.actions.find(one => one.name === activityIn(moved.motion, frame))?.activity?.label
      const said = isQuoting ? `“${saying?.text}”` : (pastime?.[locale.code] ?? pastime?.en ?? words(labelShown))
      // It faces the way it walks, else the agent finishing as it says goodbye, else the
      // first; through an action, the way it faced as the action began.
      const finishing = visible.slice(0, drawnCount).findLastIndex(one => one.leaving !== undefined)
      const facesNow = faceFor(isOnTheMove, stage.walk?.facing ?? 1, drawn, Math.max(finishing, 0))
      const once = moved.motion.once
      const held = holdFacing(heldFacing, once?.isAction ? once : undefined, facesNow, isOnTheMove)
      heldFacing = held.held
      const facing = held.side
      const body = facingFrame(blinkFrame ?? moved.frame, facing, pack.mirrors)

      const art: Art = { ...mainSize, fps: pack.fps, art: artOf(body, pack.colors) }
      const rasters: Record<string, string> = {}
      for (const index of [...drawn.left, ...drawn.right]) {
        const one = visible[index]
        if (one === undefined) continue
        // The ones still at work on the side it faces jump while it startles them, their
        // jump played from its first frame as it does, not with the clock.
        const startledAt = sideIn(drawn, index) === facing && one.leaving === undefined ? moved.startled : undefined
        const miniFrames = pack.mini?.[one.leaving?.mood ?? (startledAt === undefined ? 'working' : 'startled')] ?? []
        const mini = miniFrames[(startledAt ?? frame) % miniFrames.length] ?? []
        rasters[`mini-${one.id}`] = encode(mini, { ...pack.colors, [pack.tint]: one.color })
      }
      const leftColumns = drawn.left.length * width + (showsMore && drawn.more === -1 ? extraColumns : 0)
      const marginLeft = standX - leftColumns
      const layout = JSON.stringify([said, marginLeft, drawn.left, drawn.right, drawn.more, showsMore])
      return { shot: { layout, main: JSON.stringify(art.art), art, rasters }, said, marginLeft, drawn, showsMore }
    }

    const { shot, said, marginLeft, drawn, showsMore } = play()
    sentMain = shot.main
    // What it shows that runs out on its own: a reaction, a line it says, a look at
    // the prompt, an agent saying goodbye. The rest that changes with time alone
    // waits for the clock's redraw now and then.
    const soonest = Math.min(
      ...[flash?.until, saying?.until, typedAt === null ? undefined : typedAt + TYPING_MS, ...list.map(one => one.leaving?.until)].filter(
        (until): until is number => until !== undefined && until > now,
      ),
    )
    scene = {
      requestId: e.requestId,
      shot,
      play: () => play().shot,
      redrawAt: frame + Math.ceil(((soonest - now) / 1000) * pack.fps),
      isAsleep: lastState === 'asleep',
    }

    const { Box, Client, Raster, Text } = $.ui.resolve(e)
    const agentPet = (index: number, side: Side) => {
      const one = visible[index]
      if (one === undefined) return null
      return (
        // On the left the slot hugs the pet too: its pet and words lean right.
        <Box
          key={one.id}
          flexDirection="column"
          width={slot}
          alignItems={side === 1 ? 'flex-start' : 'flex-end'}
          marginLeft={side === 1 ? 1 : 0}
          marginRight={side === 1 ? 0 : 1}
        >
          <Raster key={`mini-${one.id}`} {...miniSize} cells={shot.rasters[`mini-${one.id}`] ?? ''} />
          {showsAgentLabels && <Text bold>{short(one.type, slot)}</Text>}
          {showsAgentLabels && <Text dimColor>{short(agentWords(one), slot)}</Text>}
        </Box>
      )
    }

    return (
      <Box flexDirection="column">
        {showsLine && (
          <Text>
            <Text bold>Claude</Text> <Text dimColor>· {said}{extra}</Text>
          </Text>
        )}
        <Box flexDirection="row" marginLeft={marginLeft}>
          {showsMore && drawn.more === -1 && (
            <Box width={OVERFLOW_COLUMNS}>
              <Text dimColor>+{hidden}</Text>
            </Box>
          )}
          {[...drawn.left].reverse().map(i => agentPet(i, -1))}
          <Client key="touch" module="./touch.tsx" props={shot.art} width={mainSize.columns} height={mainSize.rows} />
          {drawn.right.map(i => agentPet(i, 1))}
          {showsMore && drawn.more === 1 && <Text dimColor> +{hidden}</Text>}
        </Box>
      </Box>
    )
  })
}

